CREATE    PROCEDURE [synapse_ce].[usp_Insert_apuk_cpdactivity]
AS
BEGIN


	DROP TABLE IF EXISTS #tempCPDActivity

	SELECT 
		stg.[apuk_activitydate],
		stg.[apuk_activitydescription],
		stg.[apuk_activitytype],
		stg.[apuk_contactid],
		stg.[apuk_contactid_entitytype],
		stg.[apuk_contactidname],
		stg.[apuk_contactidyominame],
		stg.[apuk_cpdactivityid],
		stg.[apuk_cpdannualsummaryid],
		stg.[apuk_cpdannualsummaryid_entitytype],
		stg.[apuk_cpdannualsummaryidname],
		stg.[apuk_datecompleted],
		stg.[apuk_daterecorded],
		stg.[apuk_eligible],
		stg.[apuk_ethics],
		stg.[apuk_ethicsdescription],
		stg.[apuk_eventregistrationid],
		stg.[apuk_eventregistrationid_entitytype],
		stg.[apuk_eventregistrationidname],
		stg.[apuk_formalinformal],
		stg.[apuk_name],
		stg.[apuk_numberofhours],
		stg.[apuk_otherdescription],
		stg.[apuk_outcometext],
		stg.[apuk_overrideeligibilitycheck],
		stg.[apuk_source],
		stg.[createdby],
		stg.[createdby_entitytype],
		stg.[createdbyname],
		stg.[createdbyyominame],
		stg.[createdon],
		stg.[createdonbehalfby],
		stg.[createdonbehalfby_entitytype],
		stg.[createdonbehalfbyname],
		stg.[createdonbehalfbyyominame],
		stg.[Id],
		stg.[importsequencenumber],
		stg.[modifiedby],
		stg.[modifiedby_entitytype],
		stg.[modifiedbyname],
		stg.[modifiedbyyominame],
		stg.[modifiedon],
		stg.[modifiedonbehalfby],
		stg.[modifiedonbehalfby_entitytype],
		stg.[modifiedonbehalfbyname],
		stg.[modifiedonbehalfbyyominame],
		stg.[overriddencreatedon],
		stg.[ownerid],
		stg.[ownerid_entitytype],
		stg.[owneridname],
		stg.[owneridtype],
		stg.[owneridyominame],
		stg.[owningbusinessunit],
		stg.[owningbusinessunit_entitytype],
		stg.[owningbusinessunitname],
		stg.[owningteam],
		stg.[owningteam_entitytype],
		stg.[owninguser],
		stg.[owninguser_entitytype],
		stg.[SinkCreatedOn],
		stg.[SinkModifiedOn],
		stg.[statecode],
		stg.[statuscode],
		stg.[timezoneruleversionnumber],
		stg.[utcconversiontimezonecode],
		stg.[versionnumber],
		ROW_NUMBER() OVER(PARTITION BY ID ORDER BY ID DESC) AS RowNo
	INTO #tempCPDActivity
	FROM [staging_ce].[apuk_cpdactivity] stg
	

	INSERT INTO [synapse_ce].[apuk_cpdactivity]
	(
		[apuk_activitydate],
		[apuk_activitydescription],
		[apuk_activitytype],
		[apuk_contactid],
		[apuk_contactid_entitytype],
		[apuk_contactidname],
		[apuk_contactidyominame],
		[apuk_cpdactivityid],
		[apuk_cpdannualsummaryid],
		[apuk_cpdannualsummaryid_entitytype],
		[apuk_cpdannualsummaryidname],
		[apuk_datecompleted],
		[apuk_daterecorded],
		[apuk_eligible],
		[apuk_ethics],
		[apuk_ethicsdescription],
		[apuk_eventregistrationid],
		[apuk_eventregistrationid_entitytype],
		[apuk_eventregistrationidname],
		[apuk_formalinformal],
		[apuk_name],
		[apuk_numberofhours],
		[apuk_otherdescription],
		[apuk_outcometext],
		[apuk_overrideeligibilitycheck],
		[apuk_source],
		[createdby],
		[createdby_entitytype],
		[createdbyname],
		[createdbyyominame],
		[createdon],
		[createdonbehalfby],
		[createdonbehalfby_entitytype],
		[createdonbehalfbyname],
		[createdonbehalfbyyominame],
		[Id],
		[importsequencenumber],
		[modifiedby],
		[modifiedby_entitytype],
		[modifiedbyname],
		[modifiedbyyominame],
		[modifiedon],
		[modifiedonbehalfby],
		[modifiedonbehalfby_entitytype],
		[modifiedonbehalfbyname],
		[modifiedonbehalfbyyominame],
		[overriddencreatedon],
		[ownerid],
		[ownerid_entitytype],
		[owneridname],
		[owneridtype],
		[owneridyominame],
		[owningbusinessunit],
		[owningbusinessunit_entitytype],
		[owningbusinessunitname],
		[owningteam],
		[owningteam_entitytype],
		[owninguser],
		[owninguser_entitytype],
		[SinkCreatedOn],
		[SinkModifiedOn],
		[statecode],
		[statuscode],
		[timezoneruleversionnumber],
		[utcconversiontimezonecode],
		[versionnumber]
	)
	SELECT 
		stg.[apuk_activitydate],
		stg.[apuk_activitydescription],
		stg.[apuk_activitytype],
		stg.[apuk_contactid],
		stg.[apuk_contactid_entitytype],
		stg.[apuk_contactidname],
		stg.[apuk_contactidyominame],
		stg.[apuk_cpdactivityid],
		stg.[apuk_cpdannualsummaryid],
		stg.[apuk_cpdannualsummaryid_entitytype],
		stg.[apuk_cpdannualsummaryidname],
		stg.[apuk_datecompleted],
		stg.[apuk_daterecorded],
		stg.[apuk_eligible],
		stg.[apuk_ethics],
		stg.[apuk_ethicsdescription],
		stg.[apuk_eventregistrationid],
		stg.[apuk_eventregistrationid_entitytype],
		stg.[apuk_eventregistrationidname],
		stg.[apuk_formalinformal],
		stg.[apuk_name],
		stg.[apuk_numberofhours],
		stg.[apuk_otherdescription],
		stg.[apuk_outcometext],
		stg.[apuk_overrideeligibilitycheck],
		stg.[apuk_source],
		stg.[createdby],
		stg.[createdby_entitytype],
		stg.[createdbyname],
		stg.[createdbyyominame],
		stg.[createdon],
		stg.[createdonbehalfby],
		stg.[createdonbehalfby_entitytype],
		stg.[createdonbehalfbyname],
		stg.[createdonbehalfbyyominame],
		stg.[Id],
		stg.[importsequencenumber],
		stg.[modifiedby],
		stg.[modifiedby_entitytype],
		stg.[modifiedbyname],
		stg.[modifiedbyyominame],
		stg.[modifiedon],
		stg.[modifiedonbehalfby],
		stg.[modifiedonbehalfby_entitytype],
		stg.[modifiedonbehalfbyname],
		stg.[modifiedonbehalfbyyominame],
		stg.[overriddencreatedon],
		stg.[ownerid],
		stg.[ownerid_entitytype],
		stg.[owneridname],
		stg.[owneridtype],
		stg.[owneridyominame],
		stg.[owningbusinessunit],
		stg.[owningbusinessunit_entitytype],
		stg.[owningbusinessunitname],
		stg.[owningteam],
		stg.[owningteam_entitytype],
		stg.[owninguser],
		stg.[owninguser_entitytype],
		stg.[SinkCreatedOn],
		stg.[SinkModifiedOn],
		stg.[statecode],
		stg.[statuscode],
		stg.[timezoneruleversionnumber],
		stg.[utcconversiontimezonecode],
		stg.[versionnumber]	
	FROM #tempCPDActivity stg --[staging_ce].[apuk_cpdactivity] stg
		LEFT JOIN [synapse_ce].[apuk_cpdactivity] tgt
			ON tgt.[id] = stg.[id]
	WHERE 
		stg.[RowNo] = 1
		AND tgt.[id] IS NULL
END
